/*
 * If your child theme has more than one .css file (eg. ie.css, style.css, main.css) then
 * you will have to make sure to maintain all of the parent theme dependencies.
 *
 * Make sure you're using the correct handle for loading the parent theme's styles.
 * Failure to use the proper tag will result in a CSS file needlessly being loaded twice.
 * This will usually not affect the site appearance, but it's inefficient and extends your page's loading time.
 *
 * @link https://developer.wordpress.org/themes/advanced-topics/child-themes/
 */

function buddyx_child_enqueue_styles()
{
    wp_enqueue_style('buddyx-style', get_template_directory_uri() . '/style.css');
    wp_enqueue_style(
        'buddyx-child-style',
        get_stylesheet_directory_uri() . '/style.css',
        array('buddyx-style'),
        wp_get_theme()->get('Version')
    );
}

add_action('wp_enqueue_scripts', 'buddyx_child_enqueue_styles');

if (get_stylesheet() !== get_template()) {
    add_filter(
        'pre_update_option_theme_mods_' . get_stylesheet(),
        function ($value, $old_value) {
            update_option('theme_mods_' . get_template(), $value);
            return $old_value; // prevent update to child theme mods.
        },
        10,
        2
    );
    add_filter(
        'pre_option_theme_mods_' . get_stylesheet(),
        function (
            $default_values
        ) {
            return get_option('theme_mods_' . get_template(), $default_values);
        }
    );
}

// Register URL
add_filter('register_url', function ($register_url) {
    return home_url('/login/signup/');
});
add_filter('show_admin_bar', '__return_false');
add_action('template_redirect', function () {

    if (is_front_page() || is_home()) {
        wp_redirect(home_url('/maps/'), 301);
        exit;
    }
});

/**
 * Redirect sau khi logout
 */
add_action('wp_logout', 'pts_logout_redirect');

function pts_logout_redirect()
{
    wp_safe_redirect('/maps/');
    exit;
}
add_action('wp_footer', function () {
?>
    <script>
        (function() {

            // Đã có cookie thì không xử lý nữa
            if (document.cookie.includes('googtrans=')) {
                return;
            }

            // Ngôn ngữ trình duyệt
            let lang = (navigator.language || navigator.userLanguage || 'en')
                .toLowerCase()
                .split('-')[0];

            // Danh sách ngôn ngữ đã bật trong GTranslate
            const supported = [
                'vi', 'en', 'ja', 'ko', 'zh', 'fr', 'de', 'es', 'it', 'pt',
                'ru', 'ar', 'th', 'id', 'ms', 'hi', 'nl', 'pl', 'tr',
                'cs', 'da', 'fi', 'el', 'he', 'hu', 'no', 'ro', 'sv', 'uk'
            ];

            if (supported.includes(lang)) {
                document.cookie = `googtrans=/en/${lang}; path=/`;
                location.reload();
            }

        })();
    </script>
<?php
});
